package net.civeira.phylax.feature.access.userverificationcode.domain;

import java.time.LocalDateTime;
import java.time.ZoneId;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.identity.user.domain.UserReference;

class UserVerificationCodeChangeSetUnitTest {

  /**
   * @autogenerated CachedGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_user_verification_code_change_set_builder() {
    UserVerificationCodeChangeSet one = new UserVerificationCodeChangeSet().uid("one")
        .user(UserReference.of("one")).purpose(UserVerificationCodePurposeOptions.PASSWORD_RECOVERY)
        .codeHashPlain("one").returnUrl("one").expiresAt(LocalDateTime.of(1980, 8, 20, 0, 0)
            .atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime())
        .version(1).newUid();
    one.uid("two");
    Assertions.assertEquals("two", one.getUid().get(), "Value must equals to the assigned value");
    one.unset("uid");
    Assertions.assertFalse(one.getUid().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals(UserReference.of("one"), one.getUser().get(),
        "Value must equals to the intial value");
    one.user(UserReference.of("two"));
    Assertions.assertEquals(UserReference.of("two"), one.getUser().get(),
        "Value must equals to the assigned value");
    one.unset("user");
    Assertions.assertFalse(one.getUser().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals(UserVerificationCodePurposeOptions.PASSWORD_RECOVERY,
        one.getPurpose().get(), "Value must equals to the intial value");
    one.purpose(UserVerificationCodePurposeOptions.EMAIL_VERIFICATION);
    Assertions.assertEquals(UserVerificationCodePurposeOptions.EMAIL_VERIFICATION,
        one.getPurpose().get(), "Value must equals to the assigned value");
    one.unset("purpose");
    Assertions.assertFalse(one.getPurpose().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getReturnUrl().get(),
        "Value must equals to the intial value");
    one.returnUrl("two");
    Assertions.assertEquals("two", one.getReturnUrl().get(),
        "Value must equals to the assigned value");
    one.unset("returnUrl");
    Assertions.assertFalse(one.getReturnUrl().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getExpiresAt().get(), "Value must equals to the intial value");
    one.expiresAt(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    Assertions.assertEquals(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getExpiresAt().get(), "Value must equals to the assigned value");
    one.unset("expiresAt");
    Assertions.assertFalse(one.getExpiresAt().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(0, one.getVersion().get(), "Value must equals to the intial value");
    one.version(2);
    Assertions.assertEquals(2, one.getVersion().get(), "Value must equals to the assigned value");
    one.unset("version");
    Assertions.assertFalse(one.getVersion().isPresent(),
        "After unset, the valeue must be dissapear");
  }
}
